package com.sky.controller.admin;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import com.sky.result.Result;
import com.sky.service.DishService;
import org.springframework.data.redis.core.RedisTemplate;

@ExtendWith(MockitoExtension.class)
@DisplayName("DishController StartOrStop 方法单元测试")
class DishControllerTest {

    @InjectMocks
    private DishController dishController;

    @Mock
    private DishService dishService;

    @Mock
    private RedisTemplate<String, Object> redisTemplate;

    @Test
    @DisplayName("正向测试：当提供有效的状态和ID时，startOrStop方法应成功执行并返回成功结果")
    void startOrStop_validInput_shouldReturnSuccess() {
        // 准备测试数据
        Integer status = 1;
        Long id = 1L;

        // 模拟依赖行为
        doNothing().when(dishService).startOrStop(status, id);
        Set<String> mockKeys = new HashSet<>();
        mockKeys.add("dish_mockKey");
        when(redisTemplate.keys("dish_*")).thenReturn(mockKeys);
        when(redisTemplate.delete(mockKeys)).thenReturn(1L);

        // 执行被测方法
        Result<String> result = dishController.startOrStop(status, id);

        // 验证结果和交互
        assertNotNull(result);
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(mockKeys);
    }

    @Test
    @DisplayName("边界测试：修复后，原来导致MissingPathVariableException的输入现在不再抛出异常")
    void startOrStop_previouslyExceptionalInput_shouldNotThrowException() {
        // 准备测试数据：使用正确的路径变量名称 'status1' 对应的值
        Integer status = 0; // 代表停用
        Long id = 100L;

        // 模拟依赖行为
        doNothing().when(dishService).startOrStop(status, id);
        when(redisTemplate.keys("dish_*")).thenReturn(Collections.emptySet());
        when(redisTemplate.delete(anyCollection())).thenReturn(0L);

        // 执行被测方法，确保不抛出 MissingPathVariableException
        assertDoesNotThrow(() -> dishController.startOrStop(status, id));

        // 验证交互
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
    }

    @Test
    @DisplayName("空值测试：当id为null时，方法应正常处理并返回成功结果")
    void startOrStop_nullId_shouldHandleGracefully() {
        // 准备测试数据
        Integer status = 1;
        Long id = null;

        // 模拟依赖行为
        doNothing().when(dishService).startOrStop(status, id);
        when(redisTemplate.keys("dish_*")).thenReturn(Collections.emptySet());
        when(redisTemplate.delete(anyCollection())).thenReturn(0L);

        // 执行被测方法
        Result<String> result = dishController.startOrStop(status, id);

        // 验证结果和交互
        assertNotNull(result);
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
    }
}
